#define pi 3.14159265359
vec4 quatMultiply(vec4 u, vec4 v) {
    return vec4(
        (u.x*v.x-u.y*v.y-u.z*v.z-u.w*v.w), // 1
        (u.x*v.y+u.y*v.x-u.z*v.w+u.w*v.z), // i
        (u.x*v.z+u.y*v.w+u.z*v.x-u.w*v.y), // j
        (u.x*v.w-u.y*v.z+u.z*v.y+u.w*v.x)  // k
    );
}
vec4 quatConjugate(vec4 q) {
    return vec4(-q.x, -q.y, -q.z, q.w);
}
vec4 quatFromAxisAngle(vec3 axis, float angle) {
    float halfAngle = angle * 0.5;
    float sinHalf = sin(halfAngle);
    return vec4(axis * sinHalf, cos(halfAngle));
}
vec3 quatRotate(vec4 q, vec3 v) {
    vec4 p = vec4(v, 0.0);
    vec4 q_conj = quatConjugate(q);
    vec4 rotated = quatMultiply(quatMultiply(q, p), q_conj);
    return rotated.xyz;
}


float SDF(vec3 p) {

    // Rotation
    vec2 mouse = iMouse.xy/iResolution.xy+0.5;
    mouse.y=-mouse.y;
    if (mouse.y<0.0)mouse.x=-mouse.x;
    if (mouse.x<0.0)mouse.y=-mouse.y;
    float rx = -(mouse.y - 0.5) * 3.14159;
    float ry = (mouse.x - 0.5) * 6.28318;
    if (length(iMouse.xy)<50.0) { rx=iTime/4.0+pi/5.0; ry=rx; }
    vec4 RX = quatFromAxisAngle(vec3(1, 0, 0), rx);
    vec4 RY = quatFromAxisAngle(vec3(0, 1, 0), ry);
    vec4 RXY = quatMultiply(RX, RY);
    p = quatRotate(RXY, p);

    // Curvature
    vec4 rotX = quatFromAxisAngle(vec3(1, 0, 0), 2.0*p.x+iTime);
    vec4 rotY = quatFromAxisAngle(vec3(0, 1, 0), 2.0*p.y-iTime);
    vec4 rotZ = quatFromAxisAngle(vec3(0, 0, 1), 2.0*p.z+iTime);
    vec4 rotXY = quatMultiply(rotX, rotY);
    vec4 totalRot = quatMultiply(rotXY, rotZ);
    p = quatRotate(totalRot, p);

    return max(abs(p.y), length(p.xz)-4.0); // Disk in plane y=0
}

vec3 color(vec3 p) {
    const float eps = 0.001;
    vec3 normal = normalize(vec3(
        SDF(p + vec3(eps, 0, 0)) - SDF(p - vec3(eps, 0, 0)),
        SDF(p + vec3(0, eps, 0)) - SDF(p - vec3(0, eps, 0)),
        SDF(p + vec3(0, 0, eps)) - SDF(p - vec3(0, 0, eps))
    )); return 1.0-(normal*0.5+0.5);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float time = iTime;
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / min(iResolution.x, iResolution.y);

    vec3 ro = vec3(0, 0, -16.0);
    vec3 rd = normalize(vec3(uv, 3));

    float t = 0.0; vec3 p;
    for(int i = 0; i < 256; i++) {
        p = ro + rd * t;
        float d = SDF(p)/15.0;
        if(d < 0.0015) break;
        if(t > 20.0) break;
        t += d;
    }

    if(t < 20.0) fragColor = vec4(color(p), 1.0);
    else fragColor = vec4(0,0,0,1.0);
}
